import { useState } from 'react';
import { Badge, Code, Modal, Paper, Table, Text } from '@mantine/core';
import { useAllOf, useList } from '../api/hooks';
import type { Report } from '../api/types';
import { AbsoluteTime, PageHeader, QueryState } from '../components/common';
import { useI18n } from '../i18n/I18nProvider';

/**
 * On-call quality reports (Enterprise). The digest itself is generated by the
 * run-report job; this page lists what it stored and shows the same plain text
 * that went out by e-mail and ChatOps — summary_text is the one renderer, so the
 * three cannot disagree.
 */
export function ReportsPage() {
  const { t, fmt } = useI18n();
  const reports = useList('reports', { limit: 100, sort: 'period_start', order: 'desc' });
  const teams = useAllOf('teams');
  const teamName = new Map((teams.data ?? []).map((team) => [team.id, team.name]));
  const [open, setOpen] = useState<Report | null>(null);

  return (
    <>
      <PageHeader title={t('reports.title')} description={t('reports.description')} />
      <Paper withBorder>
        <QueryState
          query={reports}
          isEmpty={(data) => data.items.length === 0}
          emptyLabel={t('reports.empty')}
        >
          {(data) => (
            <Table highlightOnHover verticalSpacing="sm">
              <Table.Thead>
                <Table.Tr>
                  <Table.Th>{t('reports.period')}</Table.Th>
                  <Table.Th>{t('reports.team')}</Table.Th>
                  <Table.Th>{t('reports.lateAck')}</Table.Th>
                  <Table.Th>{t('reports.generated')}</Table.Th>
                </Table.Tr>
              </Table.Thead>
              <Table.Tbody>
                {data.items.map((report) => (
                  <Table.Tr
                    key={report.id}
                    style={{ cursor: 'pointer' }}
                    onClick={() => setOpen(report)}
                  >
                    <Table.Td>
                      <Text size="sm">
                        {fmt.date(report.period_start)} — {fmt.date(report.period_end)}
                      </Text>
                    </Table.Td>
                    <Table.Td>
                      {report.team_id ? (
                        <Text size="sm">{teamName.get(report.team_id) ?? report.team_id}</Text>
                      ) : (
                        <Badge variant="light" color="gray">
                          {t('reports.installation')}
                        </Badge>
                      )}
                    </Table.Td>
                    <Table.Td>
                      <Badge
                        variant="light"
                        color={report.ack.late_share > 0.1 ? 'red' : report.ack.late > 0 ? 'yellow' : 'teal'}
                      >
                        {fmt.percent(report.ack.late_share)} ({report.ack.late}/{report.ack.matured})
                      </Badge>
                    </Table.Td>
                    <Table.Td>
                      <AbsoluteTime value={report.generated_at} />
                    </Table.Td>
                  </Table.Tr>
                ))}
              </Table.Tbody>
            </Table>
          )}
        </QueryState>
      </Paper>

      <Modal
        opened={open !== null}
        onClose={() => setOpen(null)}
        size="xl"
        title={
          open
            ? `${t('reports.title')}: ${fmt.date(open.period_start)} — ${fmt.date(open.period_end)}`
            : ''
        }
      >
        {open && (
          <Code block style={{ whiteSpace: 'pre-wrap' }}>
            {open.summary_text}
          </Code>
        )}
      </Modal>
    </>
  );
}
